using System.Text.Json;

namespace Orkeon.Tools.Schema;

/// <summary>The parameters a tool declares.</summary>
public sealed class ParameterSchema
{
    private readonly Dictionary<string, JsonValueKind> _kinds = new();

    /// <summary>Reads the arguments of a call into a map.</summary>
    /// <param name="arguments">The JSON object of the call.</param>
    [Pure]
    public Result<ParameterMap, ParameterError> ReadAsMap(JsonElement arguments)
    {
        var values = new Dictionary<string, JsonElement>();
        return new ParameterMap(values);
    }

    /// <summary>Reads the arguments as a list.</summary>
    public IReadOnlyList<JsonElement> ReadAsList(JsonElement arguments) => [];

    public int Read(int index) => index;

    public int Read(string name) => name.Length;

    public int GetA() => 1;
    public int GetB() => 2;
    public int GetC() => 3;
    public int GetD() => 4;
    public int GetE() => 5;
    public int GetF() => 6;

    public sealed class Nested
    {
        public void Deep() { }
    }
}

/// <summary>The kinds of a parameter.</summary>
public enum ParameterKind { Text, Number }

import { readFile } from "node:fs/promises";

/**
 * The attempts of a run, on disk.
 */
export class AttemptStore {
  /** Reads one attempt by its id. */
  async read(id: string): Promise<string> {
    return readFile(id, "utf8");
  }

  private path(id: string): string {
    return `attempts/${id}.json`;
  }
}

/** The default store. */
export function defaultStore(): AttemptStore {
  return new AttemptStore();
}

